// Package twofer shares.
package twofer

import "fmt"

// ShareWith shares.
func ShareWith(name string) string {
	var who string
	who = name
	if who == "" {
		who = "you"
	}
	return fmt.Sprintf("One for %s, one for me.", who)
}

